"t:You can transfer money to your savings account online.": "audio/c36b1c1651c7b1c4.mp3",
"t:You can use your debit card to take out cash at any ATM.": "audio/f3efa12fe088515c.mp3",
"t:You can use your mileage points to buy a free ticket.": "audio/d2a72f0f922f041c.mp3",
"t:You can withdraw cash from any of our branch locations.": "audio/151d2411c6d5273c.mp3",
"t:You may return the item as long as you keep the receipt.": "audio/6c15470f55464453.mp3",
"t:You may return the item with the original receipt.": "audio/ffa49e7b2de8fe1d.mp3",
"t:You mentioned that you mostly use your phone for messages and maps and that you use about twelve gigabytes of data a month.": "audio/b9995870bbda2c1d.mp3",
"t:You must swipe your card to enter the building after 7 p.m.": "audio/a50be437d2b98d10.mp3",
"t:You must work here for one year to qualify for the bonus.": "audio/38faa66b064b5a13.mp3",
